query:
NODE VALUE out_count SumAgg<INT64> = 0
TABLE degrees {id STRING, degree INT64}

MATCH (s:player)-[e:follow]->(t:player)
PER PATH {
  SET s.@out_count += 1
}

MATCH (p:player)
PER NODE (p) {
  EXPORT p.id AS id, p.@out_count AS degree INTO degrees
}

FOR row IN degrees
RETURN row.id AS id, row.degree AS degree
